class LibraryItem:
    def __init__(self, late_days):
        self.late_days = late_days

    def calculate_late_fee(self):
        pass


class Book(LibraryItem):
    def __init__(self, late_days):
        super().__init__(late_days)

    def calculate_late_fee(self):
        return self.late_days * 5


class Magazine(LibraryItem):
    def __init__(self, late_days):
        super().__init__(late_days)

    def calculate_late_fee(self):
        return self.late_days * 2


def main():
    item_type = input().strip()
    late_days = int(input().strip())

    if item_type == "book":
        item = Book(late_days)
    elif item_type == "magazine":
        item = Magazine(late_days)
    else:
        print(-1)
        return

    print(item.calculate_late_fee())


if __name__ == "__main__":
    main()
